\dfrac{2}{2 y - 1} - \dfrac{2}{2 x - 5}=- \dfrac{12}{55} \\ 
         \dfrac{2}{2 y - 1} - \dfrac{4}{2 x - 5}=- \dfrac{34}{55}
\end{cases}$ là:  
\choice
{  $ (x,y)=(10;11)$ }
   {  $ (x,y)=(7;9)$ }
     {  $ (x,y)=(3;4)$ }
    { \True $(x;y)= (5;6)$ }
\loigiai{
Đặt $\dfrac{1}{2 x - 5} = u, \dfrac{1}{2 y - 1} =v $\\
ta có hệ phương trình $\begin{cases}
- 2 u + 2 v=- \dfrac{12}{55} \\ 
                        - 4 u + 2 v=- \dfrac{34}{55}
\end{cases}$\\
$\begin{cases}
u=\dfrac{1}{5} \\ 
                        v=\dfrac{1}{11}
\end{cases}$\\
$\begin{cases}
\dfrac{1}{2 x - 5}=\dfrac{1}{5} \\ 
                        \dfrac{1}{2 y - 1}=\dfrac{1}{11}
\end{cases}$\\
$\begin{cases}
x=5 \\ 
                            y=6
\end{cases}$
}\end{ex}

